CREATE TRIGGER `T257_trigger_apos_exclusao` AFTER DELETE ON `T257` FOR EACH ROW BEGIN
	DECLARE xT256_Id int(10) default 0;
	DECLARE xD009_Id int(10) default 0;
	SELECT T256_Id, T256_D009_Id INTO xT256_Id, xD009_Id FROM T256 WHERE T256_Id=OLD.T257_T256_Id;
  	UPDATE T256 SET T256_Quantidade_Entrada_Estoque = IFNULL((SELECT SUM(IFNULL(T001_Quantidade,0)) FROM T257 LEFT JOIN T001 ON T001_T257_Id=T257_Id WHERE T257_T256_Id = T256_Id),0), T256_Quantidade_Produzida = IFNULL((SELECT SUM(IFNULL(T257_Quantidade,0)) FROM T257 WHERE T257_T256_Id = T256_Id),0), T256_Quantidade_Saldo = T256_Quantidade - IFNULL((SELECT SUM(IFNULL(T257_Quantidade,0)) FROM T257 WHERE T257_T256_Id = T256_Id),0) WHERE T256_Id=xT256_Id;
  	UPDATE D009 SET D009_Quantidade_OP=D009_Quantidade_OP(D009_Id) where D009_Id=xD009_Id;
END;
